using Microsoft.AspNetCore.Mvc;
using seed_a_backend.Api.Application;
using seed_a_backend.Api.Controllers.Dtos;

namespace seed_a_backend.Api.Controllers;

[ApiController]
[Route("api/events")]
public class EventsController(EventQueryService eventQueryService) : ControllerBase
{
    [HttpGet]
    public async Task<ActionResult<IEnumerable<EventSummaryDto>>> GetEvents([FromQuery] DateOnly? von, [FromQuery] DateOnly? bis, CancellationToken ct)
    {
        var summaries = await eventQueryService.GetEventSummariesAsync(von, bis, ct);
        return Ok(summaries.Select(s => new EventSummaryDto(s.Id, s.Titel, s.Spielstaette, s.Zeitpunkt)));
    }
}

