1	import { TestBed } from '@angular/core/testing';
2	import { provideRouter } from '@angular/router';
3	import { of, Subject, throwError } from 'rxjs';
4	
5	import { ProgramOverview } from './program-overview';
6	import { EventsApiService, EventsFilter } from '../../core/api/events-api.service';
7	import { EventSummary } from '../../core/api/event-summary';
8	
9	describe('ProgramOverview', () => {
10	  const events: EventSummary[] = [
11	    { id: 1, titel: 'Kammerkonzert', spielstaette: 'Nord', zeitpunkt: '2026-09-05T19:30:00' },
12	    { id: 2, titel: 'Sinfoniekonzert', spielstaette: 'Süd', zeitpunkt: '2026-09-12T20:00:00' }
13	  ];
14	
15	  function configure(eventsApiStub: Partial<EventsApiService>) {
16	    TestBed.configureTestingModule({
17	      imports: [ProgramOverview],
18	      providers: [provideRouter([]), { provide: EventsApiService, useValue: eventsApiStub }]
19	    });
20	  }
21	
22	  it('rendert eine event-card je Veranstaltung aus dem Service', () => {
23	    configure({ getEvents: () => of(events) });
24	
25	    const fixture = TestBed.createComponent(ProgramOverview);
26	    fixture.detectChanges();
27	
28	    const compiled = fixture.nativeElement as HTMLElement;
29	    const cards = compiled.querySelectorAll('app-event-card');
30	    expect(cards.length).toBe(2);
31	    expect(compiled.textContent).toContain('Kammerkonzert');
32	    expect(compiled.textContent).toContain('Sinfoniekonzert');
33	  });
34	
35	  it('zeigt den Leer-Zustand-Text, wenn der Service eine leere Liste liefert', () => {
36	    configure({ getEvents: () => of([]) });
37	
38	    const fixture = TestBed.createComponent(ProgramOverview);
39	    fixture.detectChanges();
40	
41	    const compiled = fixture.nativeElement as HTMLElement;
42	    expect(compiled.querySelectorAll('app-event-card').length).toBe(0);
43	    expect(compiled.textContent).toContain('Keine Veranstaltungen im gewählten Zeitraum/Spielstätte gefunden.');
44	  });
45	
46	  it('zeigt während des Ladens weder den Leer-Zustand noch eine Fehlermeldung', () => {
47	    configure({ getEvents: () => new Subject<EventSummary[]>() });
48	
49	    const fixture = TestBed.createComponent(ProgramOverview);
50	    fixture.detectChanges();
51	
52	    const compiled = fixture.nativeElement as HTMLElement;
53	    expect(compiled.querySelectorAll('app-event-card').length).toBe(0);
54	    expect(compiled.textContent).not.toContain('Keine Veranstaltungen im gewählten Zeitraum/Spielstätte gefunden.');
55	    expect(compiled.textContent).not.toContain('konnten nicht geladen werden');
56	  });
57	
58	  it('zeigt eine Fehlermeldung statt des Leer-Zustands, wenn der Service fehlschlägt', () => {
59	    configure({ getEvents: () => throwError(() => new Error('Netzwerkfehler')) });
60	
61	    const fixture = TestBed.createComponent(ProgramOverview);
